/**
 * Shared logging for the Slack channel pack.
 *
 * Uses the same `(line: string) => void` contract as ServeOptions.logger.
 * Lines always start with `[bdk/slack]` so Socket Mode docs and greps
 * keep working. Optional key=value fields carry correlation ids.
 */
import { SLACK_LOG_PREFIX } from "../../internal/distribution.js";
/** Format `key=value` pairs; omit null/undefined. */
export function formatSlackLogFields(fields) {
    if (fields === undefined) {
        return "";
    }
    const parts = [];
    for (const [key, value] of Object.entries(fields)) {
        if (value === undefined || value === null) {
            continue;
        }
        const rendered = typeof value === "string" && /[\s=]/.test(value) ? JSON.stringify(value) : String(value);
        parts.push(`${key}=${rendered}`);
    }
    return parts.length === 0 ? "" : ` ${parts.join(" ")}`;
}
export function formatSlackLogLine(level, message, fields) {
    const levelTag = level === "info" ? "" : `${level} `;
    return `${SLACK_LOG_PREFIX} ${levelTag}${message}${formatSlackLogFields(fields)}`;
}
export function createSlackLogger(write = (line) => console.log(line)) {
    const emit = (level, message, fields) => {
        write(formatSlackLogLine(level, message, fields));
    };
    return {
        write(line) {
            // Preserve Socket Mode messages that already include the prefix.
            write(line.startsWith(SLACK_LOG_PREFIX) ? line : `${SLACK_LOG_PREFIX} ${line}`);
        },
        debug: (message, fields) => emit("debug", message, fields),
        info: (message, fields) => emit("info", message, fields),
        warn: (message, fields) => emit("warn", message, fields),
        error: (message, fields) => emit("error", message, fields),
    };
}
/** Default logger when none is injected (console). */
export const defaultSlackLog = createSlackLogger();
